from ui import *

TABS = [('home', 'خانه', 'MHome.dc.html', 'M4 11 L12 4 L20 11 V20 H4 Z'), ('learn', 'یادگیری', 'MPaths.dc.html', 'M4 6 H20 V18 H4 Z M4 10 H20'), ('field', 'میدان', 'MField.dc.html', 'M5 12 L10 17 L19 7'), ('peers', 'همتایان', 'MPeers.dc.html', 'M8 12 a3 3 0 1 0 0.1 0 M16 12 a3 3 0 1 0 0.1 0 M3 20 a5 5 0 0 1 10 0 M11 20 a5 5 0 0 1 10 0'), ('karname', 'کارنامه', 'MKarname.dc.html', 'M6 20 V10 M12 20 V4 M18 20 V13')]

def tabbar(cur):
    items = ''.join(f'<a href="{h}" {"aria-current=\"page\" " if k == cur else ""}style="flex: 1; display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 8px 0 6px; text-decoration: none; color: {DEEP if k == cur else "#6C7290"}; font-size: 11px; font-weight: 800"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="{2.2 if k == cur else 1.8}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{d}"></path></svg>{t}</a>' for k, t, h, d in TABS)
    return f'<nav aria-label="منوی اصلی" style="position: sticky; bottom: 0; background: #FFFFFF; border-top: 1px solid #E4E7EF; display: flex; padding-bottom: 14px">{items}</nav>'

def mtop(title, back=None, right=''):
    b = f'<a href="{back}" aria-label="برگرد" style="width: 40px; height: 40px; border-radius: 12px; display: flex; align-items: center; justify-content: center; color: #3E4462; text-decoration: none; font-size: 22px">‹</a>' if back else f'<img src="{LOGO}" alt="مدرسهٔ هدایت" style="height: 30px; width: auto; max-width: 150px; object-fit: contain">'
    return f'<header style="position: sticky; top: 0; z-index: 2; background: #FFFFFF; border-bottom: 1px solid #E4E7EF; padding: 10px 14px; display: flex; align-items: center; gap: 10px; min-height: 56px; box-sizing: border-box">{b}<b style="flex: 1; font-size: 17px; font-weight: 900">{title}</b>{right}</header>'

BELL = f'<a href="#" aria-label="اعلان‌ها، ۲ تازه" style="position: relative; width: 40px; height: 40px; border-radius: 12px; display: flex; align-items: center; justify-content: center; color: #3E4462"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 16 v-5 a6 6 0 0 1 12 0 v5 l2 2 h-16z M10 21 h4"></path></svg><span style="position: absolute; top: 3px; left: 3px; min-width: 16px; height: 16px; border-radius: 8px; background: {RED}; color: #FFFFFF; font-size: 10px; font-weight: 800; display: flex; align-items: center; justify-content: center">۲</span></a>'

def mpage(name, title, header, inner, cur=None, script='class Component extends DCLogic { renderVals() { return {}; } }', h=844):
    tb = tabbar(cur) if cur else ''
    body = f'<div style="{ROOT}; min-height: 844px; display: flex; flex-direction: column; background: #F4F5F9">{header}<main style="flex: 1; padding: 14px 14px 20px; display: flex; flex-direction: column; gap: 12px">{inner}</main>{tb}</div>'
    open(P + name, 'w').write(page(title, body, script, 390, h))

mcard = lambda inner, extra='': f'<div style="{CARD}; border-radius: 18px; padding: 14px 16px; display: flex; flex-direction: column; gap: 8px; {extra}">{inner}</div>'
mbtn = lambda t, href='#', kind='primary': btn(t, href, kind).replace('min-height: 48px', 'min-height: 48px; width: 100%; box-sizing: border-box')
H2 = lambda t, link='', href='#': f'<div style="display: flex; justify-content: space-between; align-items: center; margin-top: 4px"><h2 style="margin: 0; font-size: 16px; font-weight: 900">{t}</h2>{f"<a href=\"{href}\" style=\"font-size: 13px; font-weight: 800\">{link}</a>" if link else ""}</div>'

# ---------- MLogin: ورود با کد پیامکی
inner = f'''<div style="display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 26px 0 6px"><img src="{LOGO}" alt="مدرسهٔ هدایت" style="width: 220px; max-width: 80%; height: auto"><span style="font-size: 14px; color: {MUTE}; text-align: center">یادگیری برای کار در مسجد</span></div>
{mcard(f'<b style="font-size: 18px; font-weight: 900">ورود</b><label style="display: flex; flex-direction: column; gap: 6px; font-size: 14px; font-weight: 800">شمارهٔ موبایل<input inputmode="numeric" value="۰۹۱۲۵۵۵۵۵۵۵" style="min-height: 52px; border: 1.5px solid #E4E7EF; border-radius: 14px; padding: 0 14px; font: inherit; font-size: 18px; letter-spacing: 1px"><span style="font-size: 13px; color: {MUTE}; font-weight: 500">کد ورود به همین شماره می‌آید</span></label>{mbtn("کد را بفرست")}')}
{mcard(f'<b style="font-size: 16px; font-weight: 900">کد پیامکی</b><span style="font-size: 13px; color: {MUTE}">کد به ۰۹۱۲…۵۵۵ رفت</span><div style="display: flex; gap: 8px; direction: ltr; justify-content: center">' + ''.join(f'<span style="width: 48px; height: 56px; border: 1.5px solid {DEEP if i < 3 else "#E4E7EF"}; border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 900">{c}</span>' for i, c in enumerate(['۴', '۸', '۲', '', ''])) + f'</div>{banner("error", "کد درست نیست. دوباره ببین یا کد تازه بگیر.")}{mbtn("وارد شو")}<a href="#" style="text-align: center; font-size: 14px; font-weight: 800">دوباره بفرست (۰۰:۴۱)</a>')}
<span style="font-size: 12px; color: {MUTE}; text-align: center">با ورود، قواعد حریم را می‌پذیری. روایت‌هایت فقط برای راهیار است.</span>'''
mpage('MLogin.dc.html', 'گوشی: ورود', '', inner, h=900)

