inner = tabs.replace('aria-selected="true" href="MPaths.dc.html" style="flex: 1; text-align: center; padding: 9px 0; border-radius: 10px; background: #EAEFFC; color: ' + DEEP, 'aria-selected="false" href="MPaths.dc.html" style="flex: 1; text-align: center; padding: 9px 0; border-radius: 10px; color: #3E4462').replace('aria-selected="false" href="MExplore.dc.html" style="flex: 1; text-align: center; padding: 9px 0; border-radius: 10px; color: #3E4462', 'aria-selected="true" href="MExplore.dc.html" style="flex: 1; text-align: center; padding: 9px 0; border-radius: 10px; background: #EAEFFC; color: ' + DEEP) + f'''<label style="display: flex; align-items: center; gap: 10px; background: #FFFFFF; border: 1.5px solid #E4E7EF; border-radius: 14px; padding: 0 14px; min-height: 48px"><span style="position: absolute; width: 1px; height: 1px; overflow: hidden">جست‌وجو</span><input placeholder="نوجوان، حل مسئله، روایت…" style="flex: 1; border: 0; font: inherit; font-size: 15px; outline: none"></label>
<div style="display: flex; gap: 6px; overflow-x: auto; padding-bottom: 2px">{pill('همه', '#EAEFFC', DEEP)}{pill('مسیر خرد')}{pill('مسیر میانه')}{pill('مسیر کلان')}{pill('دوره')}{pill('پخش زنده')}</div>
<div style="display: flex; flex-direction: column; gap: 8px"><sc-for list="{{{{items}}}}" as="x" hint-placeholder-count="6"><a href="MPathMicro.dc.html" style="{CARD}; border-radius: 18px; padding: 12px 14px; display: flex; gap: 12px; align-items: center; text-decoration: none; color: {INK}"><span style="width: 52px; height: 64px; border-radius: 14px; background: {{{{x.c}}}}; display: flex; align-items: center; justify-content: center; flex: none">{toranj('rgba(255,255,255,0.85)', 24)}</span><span style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px"><span style="display: flex; justify-content: space-between; font-size: 11px"><b style="color: {{{{x.ink}}}}">{{{{x.kind}}}}</b><span style="color: {MUTE}">{{{{x.by}}}}</span></span><b style="font-size: 15px; font-weight: 900">{{{{x.t}}}}</b><span style="font-size: 12px; color: #3E4462">{{{{x.meta}}}}</span></span></a></sc-for></div>
{empty('مسیری با این جست‌وجو نیست', 'فیلتر را بردار یا «همه» را ببین.', 'همه را ببین', 'MExplore.dc.html').replace('padding: 40px 32px', 'padding: 24px 16px')}'''
script = '''const KS = { macro: ['مسیر کلان', '#1E3A9E', '#1E3A9E'], mid: ['مسیر میانه', '#F08C1A', '#8A5A00'], micro: ['مسیر خرد', '#12A58E', '#0B5F52'], course: ['دوره', '#E0A300', '#8A5A00'], live: ['پخش زنده', '#D64A6A', '#A8314F'] };
const IT = [ ['micro', 'جذب نوجوان در یک ماه', 'بنیاد هدایت', '۴ هفته، با راهیار'], ['micro', 'اولین حلقهٔ خانگی', 'مجمع بانوان مسجدی', '۳ هفته، با راهیار'], ['mid', 'حل مسئلهٔ محله', 'بنیاد هدایت', 'یک فصل، ۳ دوره، گواهی'], ['macro', 'از عضو تا مربی هسته', 'کانون نوجوانان مسجد', '۳ پله، ۱۸ ماه'], ['course', 'کار با نوجوان در فضای مجازی', 'مؤسسهٔ برکت', '۵ بخش، خودآموز، آزمون'], ['live', 'مهمانی محله؛ تجربهٔ ۴۵۰۰ محله', 'شبکهٔ مساجد شهر', 'سه‌شنبه ۲۰:۳۰، ضبط می‌شود'] ];
class Component extends DCLogic { renderVals() { return { items: IT.map(([k, t, by, meta]) => ({ t, by, meta, kind: KS[k][0], c: KS[k][1], ink: KS[k][2] })) }; } }'''
mpage('MExplore.dc.html', 'گوشی: کاوش', mtop('یادگیری', right=BELL), inner, 'learn', script, 1150)

# ---------- MPathMicro
inner = f'''<section style="{CARD}; border-radius: 20px; padding: 16px; display: flex; flex-direction: column; gap: 10px; border-top: 8px solid {TEAL}"><div style="display: flex; gap: 6px; flex-wrap: wrap">{pill('مسیر خرد، ۴ هفته', '#D3EFEA', '#0B5F52')}{pill('بنیاد هدایت')}{pill('با راهیار')}</div><h1 style="margin: 0; font-size: 22px; font-weight: 900">جذب نوجوان در یک ماه</h1><p style="margin: 0; font-size: 14px; color: #3E4462; line-height: 1.8">هر هفته یک درس ۱۰ دقیقه‌ای و یک کار کوچک با نوجوانان مسجد.</p>{bar('70%', TEAL)}<span style="font-size: 12px; color: #3E4462">هفتهٔ ۳ از ۴، ۲ گام رشد تأییدشده</span>{mbtn('ادامه بده، هفتهٔ ۳', 'MLesson.dc.html')}<div style="display: flex; gap: 8px"><div style="flex: 1; padding: 8px 10px; border-radius: 12px; background: #F4F5F9"><span style="font-size: 11px; color: {MUTE}">راهیار</span><b style="display: block; font-size: 13px">حاج‌آقا محمدی</b></div><div style="flex: 1; padding: 8px 10px; border-radius: 12px; background: #F4F5F9"><span style="font-size: 11px; color: {MUTE}">گعدهٔ بعدی</span><b style="display: block; font-size: 13px">پنجشنبه ۲۰:۳۰</b></div></div></section>
{H2('چهار هفته')}
<div style="display: flex; flex-direction: column; gap: 8px"><sc-for list="{{{{weeks}}}}" as="w" hint-placeholder-count="4"><a href="{{{{w.href}}}}" style="{CARD}; border-radius: 18px; padding: 12px 14px; display: grid; grid-template-columns: 40px 1fr; gap: 12px; align-items: start; text-decoration: none; color: {INK}; border-color: {{{{w.border}}}}"><span style="width: 40px; height: 40px; border-radius: 50%; background: {{{{w.bg}}}}; color: {{{{w.c}}}}; display: flex; align-items: center; justify-content: center; font-weight: 900">{{{{w.n}}}}</span><span style="display: flex; flex-direction: column; gap: 3px"><span style="display: flex; justify-content: space-between; align-items: center"><b style="font-size: 15px; font-weight: 900">{{{{w.t}}}}</b>{pill('{{w.st}}', '{{w.sbg}}', '{{w.sc}}')}</span><span style="font-size: 12px; color: #3E4462">درس: {{{{w.lesson}}}}</span><span style="font-size: 12px; color: #3E4462">تکلیف: {{{{w.task}}}}</span></span></a></sc-for></div>'''
script = '''const W = [ ['۱', 'دیدن و شنیدن', 'نوجوان مسجد ما کیست؟ (۹ دقیقه)', 'نام و سن سه نوجوان', 'done'], ['۲', 'اعتماد', 'اولین گفت‌وگو (۱۱ دقیقه)', 'ده دقیقه گفت‌وگوی بی‌برنامه', 'done'], ['۳', 'اولین دعوت', 'دعوتی که پذیرفته می‌شود (۸ دقیقه)', 'یک نوجوان را دعوت کن', 'now'], ['۴', 'قرار ثابت', 'برنامهٔ هفتگی کم‌هزینه (۱۲ دقیقه)', 'اولین قرار هفتگی', 'lock'] ];
const ST = { done: ['تأیید شد', '#DDF5E8', '#0A7A45', '#E4E7EF', '#DDF5E8', '#0A7A45'], now: ['این هفته', '#FFF2CC', '#8A5A00', '#1E3A9E', '#1E3A9E', '#FFFFFF'], lock: ['بعداً', '#F4F5F9', '#6C7290', '#E4E7EF', '#F4F5F9', '#6C7290'] };
class Component extends DCLogic { renderVals() { return { weeks: W.map(([n, t, lesson, task, s]) => { const x = ST[s]; return { n, t, lesson, task, st: x[0], sbg: x[1], sc: x[2], border: x[3], bg: x[4], c: x[5], href: s === 'lock' ? '#' : 'MLesson.dc.html' }; }) }; } }'''
mpage('MPathMicro.dc.html', 'گوشی: مسیر خرد', mtop('مسیر خرد', 'MPaths.dc.html'), inner, 'learn', script, 1000)

# ---------- MLesson: درس صوتی با دانلود آفلاین و تکلیف
inner = f'''<span style="font-size: 12px; color: {MUTE}">جذب نوجوان در یک ماه، هفتهٔ ۳</span>
<h1 style="margin: 0; font-size: 20px; font-weight: 900; line-height: 1.5">دعوتی که پذیرفته می‌شود</h1>
<section style="{CARD}; border-radius: 20px; padding: 16px; display: flex; flex-direction: column; gap: 12px; background: {INK}; color: #FFFFFF; border: 0"><div style="display: flex; align-items: center; gap: 12px"><span style="width: 56px; height: 56px; border-radius: 50%; background: #FFFFFF; color: {INK}; display: flex; align-items: center; justify-content: center; font-size: 22px">▶</span><span style="flex: 1; display: flex; flex-direction: column; gap: 6px"><span style="height: 6px; border-radius: 3px; background: rgba(255,255,255,0.2)"><span style="display: block; height: 100%; width: 35%; border-radius: 3px; background: {YEL}"></span></span><span style="display: flex; justify-content: space-between; font-size: 12px; color: #C9D3F5"><span>۲:۵۰</span><span>۸:۱۰</span></span></span></div><div style="display: flex; gap: 8px; align-items: center; flex-wrap: wrap">{pill('۱.۵×', 'rgba(255,255,255,0.14)', '#FFFFFF')}{pill('متن درس', 'rgba(255,255,255,0.14)', '#FFFFFF')}<a href="#" style="margin-right: auto; font-size: 13px; color: #FFFFFF; font-weight: 800">دانلود برای آفلاین (۷ مگابایت)</a></div></section>
{banner('wait', 'بارگیری… ۴۰٪. اگر قطع شد، متن درس را بخوان.')}
{mcard(f'<b style="font-size: 15px">در این درس</b><span style="font-size: 14px; color: #3E4462; line-height: 1.8">دعوتِ خوب سه ویژگی دارد: کوچک است، زمان دارد و نقش می‌دهد. «سه‌شنبه ساعت شش، ده دقیقه کمک کن صندلی‌ها را بچینیم» بهتر از «بیا مسجد» است.</span>')}
{mcard(f'<div style="display: flex; justify-content: space-between; align-items: center"><b style="font-size: 15px">تکلیف این درس</b>{pill("یک هفته", "#FFF2CC", "#8A5A00")}</div><span style="font-size: 14px; color: #3E4462; line-height: 1.8">یک نوجوان را به یک کار کوچک و مشخص در مسجد دعوت کن. بعدش سه خط روایت بنویس.</span>{mbtn("تمام شد؛ تکلیف را باز کن", "MField.dc.html")}<a href="#" style="text-align: center; font-size: 14px; font-weight: 800; color: #3E4462">یک پرسش دارم</a>', f'border-color: {YEL}')}'''
mpage('MLesson.dc.html', 'گوشی: درس', mtop('درس', 'MPathMicro.dc.html'), inner, 'learn', h=1000)

# ---------- MField
inner = f'''<div style="display: flex; gap: 6px; overflow-x: auto">{pill('۱ منتظر روایت تو', '#FFF2CC', '#8A5A00')}{pill('۱ منتظر راهیار', '#EAEFFC', DEEP)}{pill('۱ برگشته', '#FBE6EB', '#A8314F')}</div>
<div style="display: flex; flex-direction: column; gap: 8px"><sc-for list="{{{{tasks}}}}" as="t" hint-placeholder-count="4"><div style="{CARD}; border-radius: 18px; padding: 14px 16px; display: flex; flex-direction: column; gap: 8px; border-color: {{{{t.border}}}}"><div style="display: flex; justify-content: space-between; gap: 8px; align-items: center"><span style="font-size: 11px; color: {MUTE}">{{{{t.path}}}}</span>{pill('{{t.st}}', '{{t.sbg}}', '{{t.sc}}')}</div><b style="font-size: 16px; font-weight: 900">{{{{t.t}}}}</b><span style="font-size: 13px; color: #3E4462; line-height: 1.7">{{{{t.d}}}}</span><a href="{{{{t.href}}}}" style="display: flex; align-items: center; justify-content: center; min-height: 44px; border-radius: 12px; background: {{{{t.bbg}}}}; color: {{{{t.bc}}}}; border: 1.5px solid {{{{t.bb}}}}; font-weight: 800; font-size: 14px; text-decoration: none">{{{{t.cta}}}}</a><span style="font-size: 12px; color: {MUTE}">{{{{t.meta}}}}</span></div></sc-for></div>
{H2('بسته‌شده‌ها', 'کارنامه', 'MKarname.dc.html')}
{mcard(f'<div style="display: flex; gap: 10px; align-items: center">{toranj(GREEN, 20)}<span style="flex: 1; display: flex; flex-direction: column"><b style="font-size: 14px">نام و سن سه نوجوان مسجد</b><span style="font-size: 12px; color: {MUTE}">جذب نوجوان، هفتهٔ ۱، تأیید ۲ آبان</span></span><span style="font-size: 12px; color: #0A7A45; font-weight: 800">گام رشد</span></div>')}'''
script = '''const T = [
  ['مسیر اصلی شریکة‌الامام، پلهٔ حلقه', 'اولین نشست حلقهٔ خانگی', 'نشست را برگزار کردی؟ سه خط بنویس: چه کردی، چه شد، چه فهمیدی.', 'need', 'MNarrate.dc.html', 'روایت بنویس', 'مهلت ۱۸ آذر'],
  ['جذب نوجوان، هفتهٔ ۳', 'یک نوجوان را دعوت کن', 'بعد از درس «اولین دعوت» باز شد.', 'open', 'MLesson.dc.html', 'درس را ببین', 'بی مهلت'],
  ['جذب نوجوان، هفتهٔ ۲', 'ده دقیقه گفت‌وگوی بی‌برنامه', 'روایتت رسیده. راهیار تا سه روز پاسخ می‌دهد.', 'wait', '#', 'روایت را ببین', 'فرستاده ۱۲ آبان'],
  ['حلقهٔ خانگی، بخش ۲', 'دعوت از چهار همسایه', 'راهیار: «اسم همسایه‌ها را بنویس، نه تعدادشان.»', 'back', 'MNarrate.dc.html', 'اصلاح کن و بفرست', 'برگشته دیروز'],
];
const ST = { need: ['منتظر روایت تو', '#FFF2CC', '#8A5A00', '#F5B700', '#0E9F5A', '#FFFFFF', '#0E9F5A'], open: ['باز', '#F4F5F9', '#3E4462', '#E4E7EF', '#FFFFFF', '#1E3A9E', '#1E3A9E'], wait: ['منتظر راهیار', '#EAEFFC', '#1E3A9E', '#E4E7EF', '#FFFFFF', '#3E4462', '#E4E7EF'], back: ['برگشته با نکته', '#FBE6EB', '#A8314F', '#F0C2CD', '#0E9F5A', '#FFFFFF', '#0E9F5A'] };
class Component extends DCLogic { renderVals() { return { tasks: T.map(([path, t, d, s, href, cta, meta]) => { const x = ST[s]; return { path, t, d, href, cta, meta, st: x[0], sbg: x[1], sc: x[2], border: x[3], bbg: x[4], bc: x[5], bb: x[6] }; }) }; } }'''
mpage('MField.dc.html', 'گوشی: میدان', mtop('میدان', right=BELL), inner, 'field', script, 1250)

# ---------- MNarrate: فرم روایت (گوشی) با ضبط صدا
inner = f'''<span style="font-size: 12px; color: {MUTE}">مسیر اصلی شریکة‌الامام، پلهٔ حلقه</span><h1 style="margin: 0; font-size: 19px; font-weight: 900; line-height: 1.5">روایت تکلیف «اولین نشست حلقهٔ خانگی»</h1>
{mcard(f'<label style="display: flex; flex-direction: column; gap: 6px; font-size: 14px; font-weight: 800">چه کردی؟<textarea rows="6" style="border: 1.5px solid #E4E7EF; border-radius: 14px; padding: 12px; font: inherit; font-size: 15px; line-height: 1.8">چهار همسایه آمدند: خانم احمدی، خانم رضوی، خانم کریمی و مادرشان. نیم ساعت قرآن و نیم ساعت حرف از بچه‌ها. قرار بعد: سه‌شنبه.</textarea><span style="font-size: 12px; color: {MUTE}; font-weight: 500">سه خط کافی است: چه کردی، چه شد، چه فهمیدی.</span></label><div style="display: flex; gap: 8px"><a href="#" style="flex: 1; display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; border-radius: 14px; border: 1.5px solid {DEEP}; color: {DEEP}; font-weight: 800; text-decoration: none; font-size: 14px">🎙 ضبط صدا، تا ۳ دقیقه</a><a href="#" style="flex: 1; display: flex; align-items: center; justify-content: center; min-height: 48px; border-radius: 14px; border: 1.5px solid #E4E7EF; color: #3E4462; font-weight: 800; text-decoration: none; font-size: 14px">عکس</a></div><div style="display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 14px; background: #F4F5F9"><span style="width: 36px; height: 36px; border-radius: 50%; background: {INK}; color: #FFFFFF; display: flex; align-items: center; justify-content: center">▶</span><span style="flex: 1; font-size: 13px">صدای ۱:۲۰</span><a href="#" style="font-size: 13px; color: #A8314F; font-weight: 800">حذف</a></div>{pill("🔒 فقط راهیار می‌بیند")}')}
{banner('error', 'روایت فرستاده نشد. پیش‌نویس روی گوشی مانده؛ با اینترنت دوباره بفرست.')}
{mbtn('روایت را بفرست')}
<span style="font-size: 12px; color: {MUTE}; text-align: center">بعد از ارسال: «رسید. راهیار تا سه روز پاسخ می‌دهد.»</span>'''
mpage('MNarrate.dc.html', 'گوشی: روایت', mtop('روایت', 'MField.dc.html'), inner, 'field', h=900)

# ---------- MPeers
inner = f'''<section style="{CARD}; border-radius: 20px; padding: 16px; display: flex; flex-direction: column; gap: 10px; border-top: 8px solid {YEL}"><span style="font-size: 12px; color: {MUTE}">گعدهٔ «جذب نوجوان»، با حاج‌آقا محمدی</span><b style="font-size: 18px; font-weight: 900">هفتهٔ سوم: اولین دعوت</b><span style="font-size: 14px; color: #3E4462">پنجشنبه ۲۰:۳۰، مسجد صاحب‌الزمان، شبستان کوچک</span><div style="display: flex; align-items: center; gap: 8px"><div style="display: flex"><sc-for list="{{{{av}}}}" as="a" hint-placeholder-count="4"><span style="width: 30px; height: 30px; border-radius: 50%; background: {{{{a.c}}}}; color: #FFFFFF; font-weight: 900; font-size: 12px; display: flex; align-items: center; justify-content: center; border: 2px solid #FFFFFF; margin-left: -8px">{{{{a.i}}}}</span></sc-for></div><span style="font-size: 12px; color: {MUTE}">۴ می‌آیند، ۲ نگفته‌اند</span></div><div style="display: flex; gap: 8px">{btn('می‌آیم').replace('padding: 0 24px', 'padding: 0; flex: 1')}{btn('نمی‌توانم', '#', 'quiet').replace('padding: 0 24px', 'padding: 0; flex: 1')}</div></section>
{mcard(f'<div style="display: flex; justify-content: space-between; align-items: center"><b style="font-size: 15px">تیم من: هستهٔ بانوان</b><a href="#" style="font-size: 13px; font-weight: 800">تیم</a></div><span style="font-size: 13px; color: #3E4462">۶ عضو، مسئول: تو. مسیر تیمی: حلقهٔ خانگی بانوان.</span>{bar("62%", TEAL)}<div style="display: flex; gap: 8px; align-items: center">{pill("کد: ۴۸۲۱۱", "#EAEFFC", DEEP)}<a href="#" style="font-size: 13px; font-weight: 800">کد را بفرست</a></div>')}
{H2('پرسش‌های مسیر', 'بپرس')}
<div style="display: flex; flex-direction: column; gap: 8px"><sc-for list="{{{{qs}}}}" as="q" hint-placeholder-count="3"><a href="#" style="{CARD}; border-radius: 16px; padding: 12px 14px; display: flex; flex-direction: column; gap: 2px; text-decoration: none; color: {INK}"><b style="font-size: 14px">{{{{q.t}}}}</b><span style="font-size: 12px; color: {MUTE}">{{{{q.m}}}}</span></a></sc-for></div>
{mcard(f'<b style="font-size: 14px">گعده‌ای برای «شریکة‌الامام» گذاشته نشده</b><span style="font-size: 13px; color: {MUTE}">راهیار زمان بگذارد، خبرت می‌کنیم.</span>')}'''
script = '''class Component extends DCLogic { renderVals() { return { av: [ { i: 'ح', c: '#1E3A9E' }, { i: 'م', c: '#0B5F52' }, { i: 'ع', c: '#A8314F' }, { i: 'ر', c: '#F08C1A' } ], qs: [ { t: 'نوجوانی که دعوت را رد کرد، دوباره دعوت کنم؟', m: 'علی احمدی، ۲ پاسخ، یکی از راهیار' }, { t: 'برنامهٔ هفتگی با بودجهٔ صفر؟', m: 'خانم زارعی، ۴ پاسخ' }, { t: 'والدین مخالف چه؟', m: 'تو، بی‌پاسخ، ۱ روز' } ] }; } }'''
mpage('MPeers.dc.html', 'گوشی: همتایان', mtop('همتایان', right=BELL), inner, 'peers', script, 1100)

# ---------- MKarname
inner = f'''<div style="display: flex; gap: 6px; overflow-x: auto">{pill('۱۱ گام رشد', '#DDF5E8', '#0A7A45')}{pill('۲ گواهی', '#EAEFFC', DEEP)}{pill('۳ مسیر در حرکت')}</div>
<div style="display: flex; flex-direction: column; gap: 8px"><sc-for list="{{{{paths}}}}" as="p" hint-placeholder-count="4"><div style="{CARD}; border-radius: 18px; padding: 14px 16px; display: flex; flex-direction: column; gap: 8px"><div style="display: flex; justify-content: space-between; gap: 8px"><span style="display: flex; flex-direction: column"><span style="font-size: 11px; color: {MUTE}">{{{{p.kind}}}}، {{{{p.by}}}}</span><b style="font-size: 16px; font-weight: 900">{{{{p.t}}}}</b></span>{pill('{{p.st}}', '{{p.sbg}}', '{{p.sc}}')}</div>{bar('{{p.w}}', '{{p.c}}')}<span style="font-size: 12px; color: #3E4462">{{{{p.d}}}}</span><div style="display: flex; gap: 6px; flex-wrap: wrap"><sc-for list="{{{{p.steps}}}}" as="s" hint-placeholder-count="4"><span style="display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 999px; background: #F4F5F9; font-size: 11px; font-weight: 800"><span style="width: 7px; height: 7px; border-radius: 50%; background: {{{{s.c}}}}"></span>{{{{s.t}}}}</span></sc-for></div></div></sc-for></div>
<div style="{CARD}; border-radius: 18px; overflow: hidden"><div style="padding: 16px; background: {DEEP}; color: #FFFFFF; display: flex; flex-direction: column; gap: 4px"><span style="font-size: 11px; color: #C9D3F5">گواهی پایان مسیر خرد</span><b style="font-size: 16px; font-weight: 900">دفتر نام و احوال محله</b><span style="font-size: 11px; color: #C9D3F5">شبکهٔ مساجد شهر، مهر ۱۴۰۵، شمارهٔ ۱۴۰۵-۰۰۸۱۲</span></div><div style="padding: 12px 16px; display: flex; gap: 8px">{btn('دریافت PDF', '#', 'ghost', True)}{btn('اشتراک', '#', 'quiet', True)}</div></div>
{mcard(f'<b style="font-size: 14px">خودسنجی این ماه (پنج پرسش مسیر شریکة‌الامام)</b><span style="font-size: 12px; color: {MUTE}">فقط تو و راهیار می‌بینید. آخرین بار ۱ آذر.</span>{mbtn("شروع، ۳ دقیقه", "#", "ghost")}')}'''
script = '''class Component extends DCLogic { renderVals() { return { paths: [
  { kind: 'مسیر اصلی', by: 'بنیاد هدایت', t: 'شریکة‌الامام', st: 'پلهٔ ۲ از ۳', sbg: '#EAEFFC', sc: '#1E3A9E', w: '52%', c: '#1E3A9E', d: '۴ گام رشد. دیدار راهیار ۱۸ آذر.', steps: [ { t: 'خانه', c: '#0E9F5A' }, { t: 'حلقه', c: '#F5B700' }, { t: 'محله', c: '#E4E7EF' } ] },
  { kind: 'مسیر خرد', by: 'بنیاد هدایت', t: 'جذب نوجوان در یک ماه', st: 'هفتهٔ ۳ از ۴', sbg: '#D3EFEA', sc: '#0B5F52', w: '70%', c: '#12A58E', d: '۲ گام رشد. تیمی.', steps: [ { t: '۱', c: '#0E9F5A' }, { t: '۲', c: '#0E9F5A' }, { t: '۳', c: '#F5B700' }, { t: '۴', c: '#E4E7EF' } ] },
  { kind: 'مسیر خرد', by: 'شبکهٔ مساجد شهر', t: 'دفتر نام و احوال محله', st: 'تمام', sbg: '#DDF5E8', sc: '#0A7A45', w: '100%', c: '#0E9F5A', d: '۲ گام رشد، مهر.', steps: [ { t: '۱', c: '#0E9F5A' }, { t: '۲', c: '#0E9F5A' } ] },
] }; } }'''
mpage('MKarname.dc.html', 'گوشی: کارنامه', mtop('کارنامه', right=BELL), inner, 'karname', script, 1200)

# ---------- MRahyar: صف روایت‌ها (راهیار در گوشی)
RTABS = lambda cur: f'<div role="tablist" style="display: flex; gap: 4px; background: #FFFFFF; border: 1px solid #E4E7EF; border-radius: 14px; padding: 4px">' + ''.join(f'<a role="tab" aria-selected="{str(k == cur).lower()}" href="{h}" style="flex: 1; text-align: center; padding: 9px 0; border-radius: 10px; background: {"#EAEFFC" if k == cur else "transparent"}; color: {DEEP if k == cur else "#3E4462"}; font-weight: 800; font-size: 13px; text-decoration: none">{t}</a>' for k, t, h in [('q', 'صف (۱۱)', 'MRahyar.dc.html'), ('a', 'کنشگران', 'MRahyarActors.dc.html'), ('g', 'گعده‌ها', '#')]) + '</div>'
inner = RTABS('q') + f'''<div style="display: flex; gap: 6px">{pill('۳ بیش از سه روز', '#FBE6EB', '#A8314F')}{pill('۱۱ منتظر', '#FFF2CC', '#8A5A00')}</div>
<section style="{CARD}; border-radius: 20px; padding: 16px; display: flex; flex-direction: column; gap: 10px; border-top: 8px solid {YEL}"><span style="font-size: 12px; color: {MUTE}">حل مسئلهٔ محله، رسیده ۴ روز پیش</span><b style="font-size: 17px; font-weight: 900">مهدی کاظمی: بوم مسئله و پنج چرا</b><div style="padding: 12px; border-radius: 14px; background: #FBFAF6; font-size: 14px; line-height: 1.9">با سه نفر از تیم بوم را پر کردیم. با سه خانواده حرف زدیم: هر سه گفتند بچه‌ها بعد از ساعت هشت جایی ندارند. ریشه: هیچ بزرگ‌تری برایشان وقت نمی‌گذارد. قدم بعد: دو پدر داوطلب شدند.</div><div style="display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: 14px; background: #F4F5F9"><span style="width: 32px; height: 32px; border-radius: 50%; background: {INK}; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-size: 13px">▶</span><span style="font-size: 13px">صدا، ۱:۲۰</span></div>
<div style="display: flex; flex-direction: column; gap: 6px"><b style="font-size: 13px">معیار این تکلیف</b><sc-for list="{{{{crit}}}}" as="c" hint-placeholder-count="3"><label style="display: flex; align-items: center; gap: 10px; min-height: 42px; padding: 0 12px; border-radius: 12px; background: #F4F5F9; font-size: 13px"><input type="checkbox" checked="{{{{c.ok}}}}" style="width: 20px; height: 20px; accent-color: {GREEN}">{{{{c.t}}}}</label></sc-for></div>
<label style="display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 800">یک جمله برای کنشگر<textarea rows="2" placeholder="یک قوت و یک قدم بعدی" style="border: 1.5px solid #E4E7EF; border-radius: 12px; padding: 10px; font: inherit; font-size: 14px"></textarea></label>
{mbtn('گام رشد را تأیید کن')}<div style="display: flex; gap: 8px">{btn('فقط بازخورد', '#', 'ghost', True).replace('padding: 0 18px', 'padding: 0; flex: 1')}{btn('برگردان با نکته', '#', 'danger', True).replace('padding: 0 18px', 'padding: 0; flex: 1')}</div></section>
{H2('بعدی‌ها در صف')}
<div style="display: flex; flex-direction: column; gap: 6px"><sc-for list="{{{{queue}}}}" as="r" hint-placeholder-count="4"><a href="#" style="{CARD}; border-radius: 16px; padding: 10px 12px; display: flex; gap: 10px; align-items: center; text-decoration: none; color: {INK}"><span style="width: 34px; height: 34px; border-radius: 50%; background: {{{{r.av}}}}; color: #FFFFFF; font-weight: 900; display: flex; align-items: center; justify-content: center; flex: none">{{{{r.i}}}}</span><span style="flex: 1; min-width: 0; display: flex; flex-direction: column"><b style="font-size: 13px">{{{{r.n}}}}</b><span style="font-size: 12px; color: {MUTE}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis">{{{{r.task}}}}</span></span><span style="font-size: 12px; font-weight: 800; color: {{{{r.ac}}}}">{{{{r.age}}}}</span></a></sc-for></div>'''
script = '''class Component extends DCLogic { renderVals() { return {
  crit: [ { t: 'ریشه با پنج چرا، نه حدس', ok: true }, { t: 'دست‌کم سه گفت‌وگوی واقعی', ok: true }, { t: 'بی نکتهٔ آبرویی', ok: false } ],
  queue: [ { i: 'ک', n: 'حاج‌آقا کریمی', task: 'منشور همکاری ارکان', age: '۳ روز', av: '#1E3A9E', ac: '#A8314F' }, { i: 'ز', n: 'خانم زارعی', task: 'نخستین حلقهٔ بانوان', age: '۲ روز', av: '#A8314F', ac: '#6C7290' }, { i: 'ص', n: 'حاج‌آقا صادقی', task: 'دفتر نام و احوال', age: 'دیروز', av: '#1E3A9E', ac: '#6C7290' }, { i: 'ع', n: 'علی احمدی', task: 'یک عقد اخوت', age: 'امروز', av: '#0B5F52', ac: '#6C7290' } ],
}; } }'''
hdr = mtop('راهیار', right=BELL)
mpage('MRahyar.dc.html', 'گوشی راهیار: صف روایت‌ها', hdr, inner, None, script, 1250)

inner = RTABS('a') + f'''<div style="display: flex; gap: 6px">{pill('همه (۱۴)', '#EAEFFC', DEEP)}{pill('جذب نوجوان (۶)')}{pill('تعیّن امامت (۸)')}</div>
<div style="display: flex; flex-direction: column; gap: 6px"><sc-for list="{{{{rows}}}}" as="r" hint-placeholder-count="7"><a href="#" style="{CARD}; border-radius: 16px; padding: 12px 14px; display: flex; gap: 10px; align-items: center; text-decoration: none; color: {INK}"><span style="width: 38px; height: 38px; border-radius: 50%; background: {{{{r.c}}}}; color: #FFFFFF; font-weight: 900; display: flex; align-items: center; justify-content: center; flex: none">{{{{r.i}}}}</span><span style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px"><b style="font-size: 14px">{{{{r.n}}}}</b><span style="font-size: 12px; color: {MUTE}">{{{{r.path}}}}، {{{{r.pos}}}}</span><span style="font-size: 12px; color: #3E4462">آخرین روایت: {{{{r.last}}}}</span></span>{pill('{{r.st}}', '{{r.sbg}}', '{{r.sc}}')}</a></sc-for></div>
<span style="font-size: 12px; color: {MUTE}; text-align: center">کنشگر تازه را برگزارکننده به تو می‌سپارد.</span>'''
script = '''const R = [ ['م', 'مهدی کاظمی', 'جذب نوجوان', 'هفتهٔ ۳', '۴ روز پیش', 'wait', '#0B5F52'], ['ک', 'حاج‌آقا کریمی', 'تعیّن امامت', 'پلهٔ امام محله', '۳ روز پیش', 'wait', '#1E3A9E'], ['ز', 'خانم زارعی', 'جذب نوجوان', 'هفتهٔ ۳', 'دیروز', 'ok', '#A8314F'], ['ص', 'حاج‌آقا صادقی', 'تعیّن امامت', 'پلهٔ امام محله', '۱۶ روز پیش', 'quiet', '#1E3A9E'], ['ع', 'علی احمدی', 'جذب نوجوان', 'هفتهٔ ۲', '۲۰ روز پیش', 'quiet', '#0B5F52'], ['ر', 'رضا نوری', 'جذب نوجوان', 'هفتهٔ ۳', 'امروز', 'wait', '#F08C1A'], ['ح', 'حاج‌آقا حسنی', 'تعیّن امامت', 'پلهٔ امام محله', 'امروز', 'ok', '#1E3A9E'] ];
const ST = { wait: ['منتظر توست', '#FFF2CC', '#8A5A00'], ok: ['در حرکت', '#DDF5E8', '#0A7A45'], quiet: ['ساکت', '#FBE6EB', '#A8314F'] };
class Component extends DCLogic { renderVals() { return { rows: R.map(([i, n, path, pos, last, s, c]) => ({ i, n, path, pos, last, c, st: ST[s][0], sbg: ST[s][1], sc: ST[s][2] })) }; } }'''
mpage('MRahyarActors.dc.html', 'گوشی راهیار: کنشگران من', hdr, inner, None, script, 1000)
print('ok')
